import{_ as t,o,c as d,a2 as c}from"./chunks/framework.BKIQXCqS.js";const p=JSON.parse('{"title":"Документация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/doc.md","filePath":"ru/doc.md"}'),r={name:"ru/doc.md"};function a(s,e,i,l,h,n){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="документация" tabindex="-1">Документация <a class="header-anchor" href="#документация" aria-label="Permalink to &quot;Документация&quot;">​</a></h1><p>Для работы расширения требуется версия <strong>Chrome 120</strong> и выше. На данный момент другие браузеры не поддерживаются.</p><h2 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h2><p>В контексте расширения, <code>правило</code> представляет собой JavaScript и/или CSS код, который задействуется на веб-страницах, соответствующих его URL паттернам.</p><h3 id="url-паттерны" tabindex="-1">URL паттерны <a class="header-anchor" href="#url-паттерны" aria-label="Permalink to &quot;URL паттерны&quot;">​</a></h3><ul><li>Паттерн выглядит как <code>&lt;scheme&gt;://&lt;host&gt;/&lt;path&gt;</code>: <code>https://site.ru/*</code>;</li><li>Несколько паттернов пишутся через запятую: <code>https://one.ru/*, https://two.ru/*</code>;</li><li>Исключение помечается <code>!</code>: <code>!https://site.ru/admin/*</code>.</li></ul><p>Расширение переводит каждый паттерн в <a href="https://developer.chrome.com/docs/extensions/develop/concepts/match-patterns" target="_blank" rel="noreferrer">формат браузера</a>, а попап и счётчик на иконке показывают ровно те сайты, где браузер выполнит правило.</p><p><strong>Паттерн со схемой</strong> используется почти как написан:</p><table tabindex="0"><thead><tr><th>Вы пишете</th><th>Правило работает на</th></tr></thead><tbody><tr><td><code>https://site.ru/*</code></td><td><code>site.ru</code> и <code>www.site.ru</code>, но не на других поддоменах</td></tr><tr><td><code>https://*.site.ru/*</code></td><td><code>site.ru</code> и всех его поддоменах</td></tr><tr><td><code>https://site.ru/path</code></td><td>страницах, начинающихся с <code>/path</code>, на <code>site.ru</code> и <code>www.site.ru</code></td></tr><tr><td><code>https://site.ru</code></td><td>всём <code>site.ru</code> и <code>www.site.ru</code></td></tr><tr><td><code>http*://site.ru</code></td><td><code>site.ru</code> и <code>www.site.ru</code> по http и https</td></tr><tr><td><code>http://localhost:*/*</code></td><td>localhost на любом порту</td></tr></tbody></table><p><strong>Паттерн без схемы</strong> означает сайт с поддоменами по http и https:</p><table tabindex="0"><thead><tr><th>Вы пишете</th><th>Правило работает на</th></tr></thead><tbody><tr><td><code>site.ru</code>, <code>*site.ru*</code>, <code>*.site.ru</code></td><td><code>site.ru</code> и всех его поддоменах</td></tr><tr><td><code>www.site.ru</code></td><td><code>www.site.ru</code> и <code>site.ru</code></td></tr><tr><td><code>пример.рф</code></td><td><code>пример.рф</code> и его поддоменах</td></tr><tr><td><code>site.ru/path</code></td><td>страницах, начинающихся с <code>/path</code>, на <code>site.ru</code> и поддоменах</td></tr><tr><td><code>/admin</code></td><td>страницах с <code>/admin</code> в пути на любом сайте</td></tr><tr><td><code>*</code></td><td>любом сайте</td></tr></tbody></table><p>Исключение со схемой используется ровно как написано: <code>https://site.ru/*, !https://www.site.ru/*</code> работает на <code>site.ru</code>, но не на <code>www.site.ru</code>. Исключение без схемы следует таблице выше: <code>!site.ru/admin</code> исключает <code>/admin</code> на <code>site.ru</code> и его поддоменах.</p><p><strong>Красным отмечается</strong> паттерн, который браузер не примет: <code>*</code> внутри хоста (<code>https://shop*.site.ru/*</code>, <code>https://site.*/*</code>) или схема, где расширение не работает (<code>chrome-extension://</code>, <code>ws://</code>). Такой паттерн пропускается, остальные паттерны правила работают. Если браузер не примет исключение, правило не выполняется нигде, пока его не исправить, — иначе оно сработало бы на исключённых страницах.</p><p>Если не обойтись без старого режима URL, можно использовать решение из <a href="/user-js-css-docs/ru/cookbook#url-соответствия-из-версии-2-x">книги рецептов</a>.</p><h3 id="своиства-javascript" tabindex="-1">Свойства JavaScript <a class="header-anchor" href="#своиства-javascript" aria-label="Permalink to &quot;Свойства JavaScript&quot;">​</a></h3><ul><li><code>Изолированная среда</code>: если включена, то JS код запускается в изолированной среде, где JS контекст страницы недоступен, но доступен DOM.</li><li><code>Все фреймы</code>: если включена, код будет внедряться во все фреймы. Каждый фрейм проверяется на соответствие изначальным URL отдельно.</li><li><code>Запускать на старте</code>: Если включено, то скрипт внедряется до построения DOM, иначе после, но до загрузки ресурсов, таких как изображения и фреймы. Обратите внимание, что событие <code>DOMContentLoaded</code> в этом случае уже срабатывать не будет.</li></ul><h3 id="своиства-css" tabindex="-1">Свойства CSS <a class="header-anchor" href="#своиства-css" aria-label="Permalink to &quot;Свойства CSS&quot;">​</a></h3><ul><li><code>Программное подключение</code>: <ul><li><strong>Включено</strong>: изначально низкий приоритет стилей, но максимальный при использовании <code>!important</code>. Доступен режим живого редактирования CSS. Можно использовать без &quot;режима разработчика&quot;.</li><li><strong>Выключено</strong>: более высокий приоритет стилей за счёт расположения <code>&lt;style/&gt;</code> в конце DOM. Недоступен режим живого редактирование CSS. Этот режим недоступен без &quot;режима разработчика&quot;.</li></ul></li><li><code>Автоматический !important</code>: добавляет <code>!important</code> ко всем свойствам CSS в уже скомпилированный код.</li></ul><h3 id="общие-правила" tabindex="-1">Общие правила <a class="header-anchor" href="#общие-правила" aria-label="Permalink to &quot;Общие правила&quot;">​</a></h3><p>&quot;Общие правила&quot; позволяют выстраивать зависимости между разными правилами и явно контролировать очерёдность их загрузки. Любое правило можно отметить как &quot;общее&quot; — это добавит его в список подключаемых модулей у остальных правил. Из подключаемых правил берётся только JS и CSS контент, остальные свойства подключаемого правила игнорируются.</p><h3 id="другие-особенности" tabindex="-1">Другие особенности <a class="header-anchor" href="#другие-особенности" aria-label="Permalink to &quot;Другие особенности&quot;">​</a></h3><ul><li>Маркер правила <code>включено</code> игнорируется в случае когда правило общее и подключается другим правилом;</li><li>Маркер <code>сохранять в облако</code> лишь указывает на включение правила в хранилище при синхронизации и не производит дополнительных действий;</li><li>Режим стилей выбирается в меню панели стилей: «Авто» (по умолчанию) — препроцессор <code>SASS</code> или <code>SCSS</code>, синтаксис определяется автоматически по наличию символов <code>{;}</code> в коде; «CSS» — стиль применяется как написан, без препроцессора.</li></ul><h2 id="модули" tabindex="-1">Модули <a class="header-anchor" href="#модули" aria-label="Permalink to &quot;Модули&quot;">​</a></h2><p>К правилам можно подключать внешние JS и CSS модули, они запускаются до правил. Поддерживаются <code>https://...</code> ссылки, тип ресурса распознаётся по расширению.</p><p>Контент модуля загружается и кешируется в хранилище расширения, для его обновления нужно нажать &quot;скачать повторно&quot; в окне редактирования.</p><h2 id="хранилище" tabindex="-1">Хранилище <a class="header-anchor" href="#хранилище" aria-label="Permalink to &quot;Хранилище&quot;">​</a></h2><p>Улучшение функционала резервных копий и синхронизации только предстоит, а пока резервные копии работают <strong>только вручную и только в режиме полной замены хранилища</strong>.</p><h3 id="google-синхронизация" tabindex="-1">Google Синхронизация <a class="header-anchor" href="#google-синхронизация" aria-label="Permalink to &quot;Google Синхронизация&quot;">​</a></h3><p>Если в браузере включена синхронизация, то можно резервные копии загружать в облако под своим Google аккаунтом. Такой метод не требует дополнительной авторизации и настройки, <code>storage.sync</code> это <a href="https://developer.chrome.com/docs/extensions/reference/api/storage#storage_areas" target="_blank" rel="noreferrer">стандартный тип синхронизации для расширений</a>.</p><p>Но он граничен 100кб, поэтому перед загрузкой из хранилища вычищается контент всех внешних ресурсов, удаляются все генеративные данные, а получившийся результат сжимается с помощью <code>CompressionStream</code>. Если вам всё равно не хватает пространства, то на маловажных скриптах можно отключить синхронизацию в облако.</p>',30)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
